			std::string topic_remove_all = "Irisviel.remove_all";
			Json::Value params_remove_all;
			Json::Value result;
			Json::Reader reader;
			std::string raw_json;
			std::string json_new = R"(
{
	"single_database_capacity":1000,
	"dimension":128,
	"working_directory":".",
	"event_id":"6de84d24-a9ff-48b7-8b36-9459146c8ffa",
	"autoAssignmentInstance":0,
	"device":-1,
	"reserved":""
})";
			Logger::WriteMessage(parser::instance().init_plugin("plugin_configure.json").c_str());
			reader.parse(raw_json = parser::instance().parse(topic_new, json_new), result);
